// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(0) && recipient != address(0) && amount > 0 && amount <= address(this).balance);
        vm.deal(address(c), amount);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, recipient));
        bool expectedSuccess = (caller == address(this));
        assertTrue(success == expectedSuccess);
    }
}
